import java.util.*; abstract class Appliance09{final double watts;Appliance09(double w){watts=w;}boolean saver(){return false;}double units(double h,boolean s){return watts*h/1000;}} class Fridge09 extends Appliance09{Fridge09(){super(150);}} class AC09 extends Appliance09{AC09(){super(1500);}boolean saver(){return true;}double units(double h,boolean s){double u=super.units(h,s);return s?u*.75:u;}} class TV09 extends Appliance09{TV09(){super(100);}} class Washer09 extends Appliance09{Washer09(){super(500);}boolean saver(){return true;}double units(double h,boolean s){double u=super.units(h,s);return s?u*.75:u;}} public class Week09Problem05{public static void main(String[]z){Scanner s=new Scanner(System.in);int n=s.nextInt();double total=0;for(int i=0;i<n;i++){String t=s.next().toUpperCase();double h=s.nextDouble();boolean save=s.next().equalsIgnoreCase("SAVER");Appliance09 a=t.equals("AC")?new AC09():t.equals("TV")?new TV09():t.equals("WASHER")?new Washer09():new Fridge09();if(save&&!a.saver()){System.out.println("Saver mode unsupported");continue;}double u=a.units(h,save),c=u*8;System.out.printf("Units: %.3f, Cost: %.2f%n",u,c);total+=c;}System.out.printf("Total cost: %.2f%n",total);}}